```c
Status ListDelete_L(LinkList &L, int i, ElemType &e) {
// 在带头结点的单链线性表 L 中，删除第 i 个元素，并由 e 返回其值
p = L; j = 0;
while (p->next && j < i-1) {    // 寻找第 i 个结点，并令 p 指向其前趋
p = p->next; ++j;
}
if (!(p->next) || j > i-1) return ERROR;    // 删除位置不合理
q = p->next;    p->next = q->next;    // 删除并释放结点
e = q->data;    free(q);
return OK;
} // ListDelete_L
```

