```txt
int LocateElem_SL(SLinkList S, ElemType e) {
// 在静态单链线性表 L 中查找第 1 个值为 e 的元素。
// 若找到，则返回它在 L 中的位序，否则返回 0。
i = S[0].cur;    // i 指示表中第一个结点
while (i && S[i].data != e) i = S[i].cur;    // 在表中顺链查找
return i;
} // LocateElem_SL
