a = GetCurElem(pa); b = GetCurElem(pb); // a 和 b 为两表中当前比较元素
if ((*compare)(a, b) <= 0) {    // a ≤ b
DelFirst(ha, q); Append(Lc, q); pa = NextPos(La, ha); }
else {    // a > b
DelFirst(hb, q); Append(Lc, q); pb = NextPos(Lb, hb); }
