ch = getchar();    // 从终端接收第一个字符
while (ch != EOF) { // EOF 为全文结束符
while (ch != EOF && ch != '\n') {
switch (ch) {
case '#': Pop(S, c);    break; // 仅当栈非空时退栈
case '@': ClearStack(S);    break; // 重置 S 为空栈
default: Push(S, ch);    break; // 有效字符进栈，未考虑栈满情形
}
ch = getchar();    // 从终端接收下一个字符
}
