{
if (n == 1)
move(x, 1, z);    // 将编号为 1 的圆盘从 x 移到 z
else {
hanoi(n-1, x, z, y);    // 将 x 上编号为 1 至 n-1 的圆盘移到 y, z 作辅助塔
move(x, n, z);    // 将编号为 n 的圆盘从 x 移到 z
hanoi(n-1, y, x, z);    // 将 y 上编号为 1 至 n-1 的圆盘移到 z, x 作辅助塔
}
}
