// 插入元素 e 为 Q 的新的队尾元素
if ((Q.rear + 1) % MAXQSIZE == Q.front) return ERROR; // 队列满
Q.base[Q.rear] = e;
Q.rear = (Q.rear + 1) % MAXQSIZE;
return OK;
}

Status DeQueue (SqQueue &Q. QElemType &e) {
// 若队列不空，则删除 Q 的队头元素，用 e 返回其值，并返回 OK；
// 否则返回 ERROR
if (Q.front == Q.rear) return ERROR;
e = Q.base[Q.front];
Q.front = (Q.front + 1) % MAXQSIZE;
return OK;
}
