OpenForDay( ):    // 初始化
while (MoreEvent) {
EventDriven(OccurTime.EventType);    // 事件驱动
switch (EventType) {
case 'A': CustomerArrived( );    break;    // 处理客户到达事件
case 'D': CustomerDeparture( );    break;    // 处理客户离开事件
default: Invalid( );
} // switch
