if (S1[0] + S2[0] <= MAXSTRLEN) {    // 未截断
T[1..S1[0]] = S1[1..S1[0]];
T[S1[0] + 1..S1[0] + S2[0]] = S2[1..S2[0]];
T[0] = S1[0] + S2[0];    uncut = TRUE;
