T[S1[0] + 1..MAXSTRLEN] = S2[1..MAXSTRLEN - S1[0]];
T[0] = MAXSTRLEN;    uncut = FALSE;
}
else {    // 截断(仅取 S1)
T[0..MAXSTRLEN] = S1[0..MAXSTRLEN];
