```c
int Index_KMP(String S, SString T, int pos) {
// 利用模式串 T 的 next 函数求 T 在主串 S 中第 pos 个字符之后的位置的
// KMP 算法。其中，T 非空，1 ≤ pos ≤ StrLength(S)。
i = pos;    j = 1;
while (i <= S[0] && j <= T[0]) {
if (j == 0 || S[i] == T[j]) {++i; ++j;}    // 继续比较后继字符
else j = next[j];    // 模式串向右移动
}
if (j > T[0]) return i - T[0];    // 匹配成功
else return 0;
} // Index_KMP
```

