Status Locate(Array A, va_list ap, int &off) {
// 若 ap 指示的各下标值合法，则求出该元素在 A 中相对地址 off
off = 0;
for (i = 0; i < A.dim; ++i) {
ind = va_arg(ap, int);
if (ind < 0 || ind >= A.bounds[i]) return OVERFLOW;
off += A.constants[i] * ind;
