return DUPLICATE;    // 表中已有与 e 有相同关键字的元素
else if (c < hashsize[H.sizeindex]/2) {    // 冲突次数 c 未达到上限，(c 的阈值可调)
H.elem[p] = e;    ++H.count;    return OK;    // 插入 e
}
else {RecreateHashTable(H); return UNSUCCESS;}    // 重建哈希表
} // InsertHash
```  
