void Adjust (LoserTree &ls, int s) {
// 沿从叶子结点 b[s] 到根结点 ls[0] 的路径调整败者树
t = (s + k) / 2;    // ls[t] 是 b[s] 的双亲结点
while t > 0) {
if (b[s].key > b[ls[t]].key) s ←→ ls[t];    // s 指示新的胜者
t = t / 2;
}
ls[0] = s;
} // Adjust
